import{z as i,x as B,o as r,c as d,q as s,j as o,D as e,d as t,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"陷阱与模拟","description":"","frontmatter":{"title":"陷阱与模拟","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/trap-and-emulate.md","filePath":"cs/trap-and-emulate.md","lastUpdated":1791413859000}'),p={name:"cs/trap-and-emulate.md"};function m(C,a,u,M,c,F){const l=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="陷阱与模拟" tabindex="-1">陷阱与模拟 <a class="header-anchor" href="#陷阱与模拟" aria-label="Permalink to &quot;陷阱与模拟&quot;">​</a></h1><div class="epigraph"><p>可虚拟化的 ISA 让敏感指令在非特权运行时陷入；VMM 模拟其效果，于是客内核以为自己仍在全特权。</p><footer>—— 据 Popek and Goldberg, Formal Requirements for Virtualizable Third Generation Architectures, CACM 1974 整理</footer></div><p><a href="/cs/seccomp-filter">上一课</a>过滤的是系统调用，对象是本机用户进程。<a href="/cs/privilege-rings">特权级</a> 已有环。<a href="/cs/container-os">容器</a> 没有第二套内核。缺口是 <strong>VMM</strong>：在宿主内核（或 type-1 监控器）上跑一个以为自己管理机器的客内核。Popek/Goldberg：敏感指令必须是特权指令，否则无法陷入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>客内核执行「改页表根、关中断、写设备」——若真执行，会毁掉宿主。若 ISA 满足条件：把客内核放在非特权环，这些指令陷入，VMM 改影子状态再返回。缺口：控制敏感（影响配置）与行为敏感（结果依赖特权模式）都必须陷入。x86 历史上一批指令不满足，于是有二进制翻译或硬件辅助（下一课 EPT）。本课不写如何从客机攻击宿主。</p><p><span class="marginnote">术语翻译：特权指令 = 低权限下执行会报错、可被拦下；敏感指令 = 会改机器配置、或结果随特权模式变。可虚拟化的关键就一句：所有敏感指令都必须是特权指令——「想越权必被抓」。</span></p><p><span class="marginnote">陷入不是 seccomp：对象是指令，不是 syscall 号。用户程序在客机里的 syscall 由客内核处理；客内核的特权指令才到 VMM。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VMM 维护客机的虚拟 CPU 状态。陷入：译码敏感指令，更新虚拟中断标志、虚拟 MMU 等，恢复客机 PC 的下一条。I/O 指令同样模拟或交给后面的 virtio 一课。与 <a href="/cs/page-fault-path">缺页路径</a> 对照：那是进程对宿主页表；这里是客机对「虚拟物理内存」的访问，可能再由 VMM 映射到真机。</p><p><span class="marginnote">直觉类比：VMM 像驾驶模拟舱——客内核转动方向盘（写虚拟页表、关虚拟中断）时，舱体把动作记下、在幕后调整布景，再让乘客以为真的开了一台车。</span></p>',10)),(r(),o(A,null,{default:e(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20GUEST%5B%22%E5%AE%A2%E5%86%85%E6%A0%B8%E9%9D%9E%E7%89%B9%E6%9D%83%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20SENS%5B%22%E6%95%8F%E6%84%9F%E6%8C%87%E4%BB%A4%22%5D%0A%20%20SENS%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%20VMM%22%5D%0A%20%20TRAP%20--%3E%20EMU%5B%22%E6%A8%A1%E6%8B%9F%E8%99%9A%E6%8B%9F%E7%8A%B6%E6%80%81%22%5D%0A%20%20EMU%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E5%AE%A2%E6%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"trap-and-emulate 让「一台机器多套内核」在软件上可陈述：每套内核操作的是虚拟资源。性能取决于陷入频率。不能虚拟化的指令必须改写客代码或靠硬件扩展。本课引用 Popek/Goldberg 的充分条件，不把现代 x86 手册逐条对照考完。",-1)),a[5]||(a[5]=E("p",null,"与用户/内核分裂：宿主仍用自己的分裂；客机有自己的一套，由 VMM 嵌套解释，直到下一课硬件嵌套页表。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为虚拟机一定比容器慢很多。开销取决于陷入频率——普通指令几乎原生速度；热点路径若频繁踩敏感指令，每次陷入-模拟-返回要上千拍，瓶颈才显形。所以调优虚拟机先找「陷入热点」。")],-1)),(r(),o(A,null,{default:e(()=>[n(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INSN%5B%22%E5%AE%A2%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20Q%7B%22%E6%98%AF%E6%95%8F%E6%84%9F%E6%8C%87%E4%BB%A4%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%99%AE%E9%80%9A%E6%8C%87%E4%BB%A4%22%7C%20NATIVE%5B%22%E7%9B%B4%E6%8E%A5%E5%9C%A8%E7%9C%9F%20CPU%20%E4%B8%8A%E8%B7%91%3Cbr%2F%3E%E4%B8%8D%E7%BB%8F%20VMM%22%5D%0A%20%20Q%20--%3E%7C%22%E6%95%8F%E6%84%9F%E4%B8%94%E4%BC%9A%E9%99%B7%E5%85%A5%22%7C%20TAE%5B%22%E9%99%B7%E5%85%A5%20VMM%3Cbr%2F%3E%E6%A8%A1%E6%8B%9F%E6%95%88%E6%9E%9C%E5%90%8E%E8%BF%94%E5%9B%9E%22%5D%0A%20%20Q%20--%3E%7C%22%E6%95%8F%E6%84%9F%E4%BD%86%E4%B8%8D%E9%99%B7%E5%85%A5%3Cbr%2F%3E%EF%BC%88%E5%8E%86%E5%8F%B2%20x86%20%E4%B8%80%E6%89%B9%E6%8C%87%E4%BB%A4%EF%BC%89%22%7C%20FIX%5B%22%E6%97%A0%E6%B3%95%E7%9B%B4%E6%8E%A5%E8%99%9A%E6%8B%9F%E5%8C%96%3Cbr%2F%3E%E4%BA%8C%E8%BF%9B%E5%88%B6%E7%BF%BB%E8%AF%91%E6%94%B9%E5%86%99%E5%AE%A2%E4%BB%A3%E7%A0%81%3Cbr%2F%3E%E6%88%96%E7%AD%89%E7%A1%AC%E4%BB%B6%E8%BE%85%E5%8A%A9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入二进制翻译的全部动态编译。不保证所有 RISC-V 虚拟化扩展细节。下一课：客机 GPA→HPA 的第二层页表，减少影子页表的软件负担。</p><p>后课默认：敏感指令可陷入模拟。客机物理地址如何硬件翻译，下一课 EPT/NPT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可虚拟化 ISA：敏感指令必陷入，VMM 模拟。</li><li>容器过滤 syscall；VMM 拦截特权指令。</li><li>嵌套页表是 EPT/NPT 的缺口。</li><li>出处：Popek and Goldberg, <em>CACM</em> 1974；Tanenbaum <em>MOS</em>。</li></ul>',5))])}const T=i(p,[["render",m]]);export{f as __pageData,T as default};
